window.__votdWeek && window.__votdWeek({"week":"2028-03-13","reading":"2 Nephi 31–33","days":[{"d":"2028-03-13","ref":"2 Nephi 31:9","b":"2 Nephi","c":31,"v":9,"he":"וְעוֹד מַרְאֶה לִבְנֵי־הָאָדָם אֶת־מֵצַר הַנָּתִיב וְאֶת־צֹר הַשַּׁעַר אֲשֶׁר־בּוֹ יָבֹאוּ בְּשׂוּמוֹ מוֹפֵת לִפְנֵיהֶם׃","en":"And again, it showeth unto the children of men the straitness of the path, and the narrowness of the gate, by which they should enter, he having set the example before them."},{"d":"2028-03-14","ref":"2 Nephi 31:12","b":"2 Nephi","c":31,"v":12,"he":"וְגַם בָּא קוֹל הַבֵּן אֵלַי לֵאמֹר הַנִּטְבָּל בִּשְׁמִי לוֹ יִתֵּן הָאָב אֶת־רוּחַ־הַקֹּדֶשׁ כָּמֹנִי לָכֵן לְכוּ אַחֲרַי וַעֲשׂוּ הַדְּבָרִים אֲשֶׁר רְאִיתֶם עָשִׂיתִי׃","en":"And also, the voice of the Son came unto me, saying: He that is baptized in my name, to him will the Father give the Holy Ghost, like unto me; wherefore, follow me, and do the things which ye have seen me do."},{"d":"2028-03-15","ref":"2 Nephi 31:15","b":"2 Nephi","c":31,"v":15,"he":"וָאֶשְׁמַע קוֹל מֵהָאָב לֵאמֹר הֵן דִּבְרֵי אֲהוּבִי אֱמֶת וְנֶאֱמָנִים הַמַּחֲזִיק עַד־הַקֵּץ הוּא יִוָּשֵׁעַ׃","en":"And I heard a voice from the Father, saying: Yea, the words of my Beloved are true and faithful. He that endureth to the end, the same shall be saved."},{"d":"2028-03-16","ref":"2 Nephi 32:3","b":"2 Nephi","c":32,"v":3,"he":"מַלְאָכִים מְדַבְּרִים בְּכֹחַ רוּחַ־הַקֹּדֶשׁ לָכֵן מְדַבְּרִים דִּבְרֵי הַמָּשִׁיחַ לָכֵן אָמַרְתִּי לָכֶם הִתְעַנְּגוּ עַל־דִּבְרֵי הַמָּשִׁיחַ כִּי הִנֵּה דִּבְרֵי הַמָּשִׁיחַ יַגִּידוּ לָכֶם אֶת־כׇּל־אֲשֶׁר תַּעֲשׂוּן׃","en":"Angels speak by the power of the Holy Ghost; wherefore, they speak the words of Christ. Wherefore, I said unto you, feast upon the words of Christ; for behold, the words of Christ will tell you all things what ye should do."},{"d":"2028-03-17","ref":"2 Nephi 32:8","b":"2 Nephi","c":32,"v":8,"he":"וְעַתָּה אַחַי הָאֲהוּבִים רֹאֶה אֲנִי כִּי־עוֹד תֶּהְגּוּ בִּלְבַבְכֶם וַיַּעֲצִבֵנִי כִּי עָלַי לְדַבֵּר עַל־הַדָּבָר הַזֶּה כִּי לוּ תַקְשִׁיבוּ לָרוּחַ הַמְלַמֵּד אָדָם לְהִתְפַּלֵּל יְדַעְתֶּם כִּי עֲלֵיכֶם לְהִתְפַּלֵּל כִּי־לֹא יְלַמֵּד רוּחַ הָרָעָה אָדָם לְהִתְפַּלֵּל כִּי־אִם יְלַמְּדֵהוּ אֲשֶׁר לֹא יִתְפַּלֵּל׃","en":"And now, my beloved brethren, I perceive that ye ponder still in your hearts; and it grieveth me that I must speak concerning this thing. For if ye would hearken unto the Spirit which teacheth a man to pray, ye would know that ye must pray; for the evil spirit teacheth not a man to pray, but teacheth him that he must not pray."},{"d":"2028-03-18","ref":"2 Nephi 32:9","b":"2 Nephi","c":32,"v":9,"he":"אַךְ הִנֵּה אֹמֵר אֲנִי לָכֶם כִּי הִתְפַּלֵּל תִּתְפַּלְלוּ תָּמִיד וְלֹא תִתְרַפּוּ כִּי עָשׂוֹת לֹא תַעֲשׂוּ דָבָר לַיהוָה בִּלְתִּי־אִם בָרִאשׁוֹנָה תִּתְפַּלְלוּ אֶל־הָאָב בְּשֵׁם הַמָּשִׁיחַ לְמַעַן יְקַדֵּשׁ אֶת־מַעֲשְׂךָ לְךָ לְמַעַן יִהְיֶה מַעֲשְׂךָ לְטוֹבַת נַפְשְׁךָ׃","en":"But behold, I say unto you that ye must pray always, and not faint; that ye must not perform any thing unto the Lord save in the first place ye shall pray unto the Father in the name of Christ, that he will consecrate thy performance unto thee, that thy performance may be for the welfare of thy soul."},{"d":"2028-03-19","ref":"2 Nephi 33:2","b":"2 Nephi","c":33,"v":2,"he":"אַךְ הִנֵּה רַבִּים מַקְשִׁים לִבָּם בְּרוּחַ־הַקֹּדֶשׁ וְאֵין־לוֹ מָקוֹם בָּם לָכֵן יַשְׁלִיכוּ דְבָרִים רַבִּים הַכְּתוּבִים וְיַחְשְׁבוּם לְאָיִן׃","en":"But behold, there are many that harden their hearts against the Holy Spirit, that it hath no place in them; wherefore, they cast many things away which are written and esteem them as things of naught."}]});
